    [pscustomobject]@{
        Repository = $run.Repository
        Stages = New-ConsoleStatusList -Layout Chain -Content {
            for ($i = 0; $i -lt $stageNames.Count; $i++) {
                @{ Key = $stageNames[$i]; Status = $run.Status[$i] }
            }
        }
    }
} | Show-ConsoleTable

